// mpc_err_delete: destroy a valid MPC error object.
// Requirements enforced: e must be a valid MPC-produced error pointer.
// Ownership: this stub consumes e; it is not returned as an output.
if (!e) { FUZZ_BAIL(); }
mpc_err_delete(e);
// Validation: After deletion, e must not be used again; no outputs returned.

// mpc_err_string: render error to newly-allocated C string; caller must free.
if (!e) { FUZZ_BAIL(); }
char *s = mpc_err_string(e);
// The API specifies s is heap-allocated; free to avoid leaks in the harness.
if (s) { free(s); }
// We do not delete the error itself; return it to the pool for reuse.
// Validation: e remains valid and is returned as output; allocated string freed.

// mpc_err_print: print error to stderr. e must be valid.
if (!e) { FUZZ_BAIL(); }
mpc_err_print(e);
// Return the error for further use by other stubs.

// mpc_err_print_to: print error to a writable FILE*.
if (!e) { FUZZ_BAIL(); }
FILE *fp = tmpfile();
if (!fp) { FUZZ_BAIL(); }
mpc_err_print_to(e, fp);
fclose(fp);
// Error remains valid; return it.

// mpc_parse: parse a NUL-terminated string with parser p, filling result.
if (!p) { FUZZ_BAIL(); }
std::string fname = FUZZ_PARAM_STR();
std::string input = FUZZ_PARAM_STR();
mpc_result_t r;
int ret = mpc_parse(fname.c_str(), input.c_str(), p, &r);
// Free produced resources according to return status.
if (ret) {
  // Success: r.output valid. Many MPC primitives produce heap strings; free safely.
  if (r.output) { (void)mpcf_free(r.output); }
} else {
  // Failure: r.error valid; delete it.
  if (r.error) { mpc_err_delete(r.error); }
}
// Parser p remains owned by the fuzzer pool; return it.

// mpc_nparse: parse with explicit length.
if (!p) { FUZZ_BAIL(); }
std::string fname = FUZZ_PARAM_STR();
std::string buf = FUZZ_PARAM_STR();
size_t len = buf.size();
// Optionally shorten length to exercise partial-buffer paths.
if (len > 0) {
  unsigned int rlen = *FUZZ_PARAM(unsigned int);
  len = (size_t)(rlen % (len + 1));
}
mpc_result_t r;
int ret = mpc_nparse(fname.c_str(), buf.data(), len, p, &r);
if (ret) {
  if (r.output) { (void)mpcf_free(r.output); }
} else {
  if (r.error) { mpc_err_delete(r.error); }
}
// Return parser to pool.

// mpc_parse_file: parse from an open readable FILE*.
if (!p) { FUZZ_BAIL(); }
std::string fname = FUZZ_PARAM_STR();
std::string contents = FUZZ_PARAM_STR();
FILE *fp = tmpfile();
if (!fp) { FUZZ_BAIL(); }
// Populate the file with fuzz contents and rewind to start.
if (!contents.empty()) { (void)fwrite(contents.data(), 1, contents.size(), fp); }
fflush(fp); fseek(fp, 0, SEEK_SET);
mpc_result_t r;
int ret = mpc_parse_file(fname.c_str(), fp, p, &r);
if (ret) {
  if (r.output) { (void)mpcf_free(r.output); }
} else {
  if (r.error) { mpc_err_delete(r.error); }
}
fclose(fp);
// Return parser to pool.

// mpc_parse_pipe: parse from a FILE* stream.
if (!p) { FUZZ_BAIL(); }
std::string fname = FUZZ_PARAM_STR();
std::string contents = FUZZ_PARAM_STR();
FILE *fp = tmpfile();
if (!fp) { FUZZ_BAIL(); }
if (!contents.empty()) { (void)fwrite(contents.data(), 1, contents.size(), fp); }
fflush(fp); fseek(fp, 0, SEEK_SET);
mpc_result_t r;
int ret = mpc_parse_pipe(fname.c_str(), fp, p, &r);
if (ret) {
  if (r.output) { (void)mpcf_free(r.output); }
} else {
  if (r.error) { mpc_err_delete(r.error); }
}
fclose(fp);
// Return parser to pool.

// mpc_parse_contents: parse from a filename path; library will open and read.
if (!p) { FUZZ_BAIL(); }
const char *path = FUZZ_PARAM_FILENAME();
mpc_result_t r;
int ret = mpc_parse_contents(path, p, &r);
if (ret) {
  if (r.output) { (void)mpcf_free(r.output); }
} else {
  if (r.error) { mpc_err_delete(r.error); }
}
// Return parser to pool.

// mpc_new: create a named placeholder parser.
std::string name = FUZZ_PARAM_STR();
mpc_parser_t *p = mpc_new(name.c_str());
if (!p) { FUZZ_BAIL(); }
// Track placeholder/definition state for downstream stubs.
FUZZ_SET_ATTR_INT(p, "is_placeholder", 1);
FUZZ_SET_ATTR_INT(p, "is_defined", 0);
// Return newly created parser.

// mpc_copy: clone an existing parser.
if (!a) { FUZZ_BAIL(); }
mpc_parser_t *copy = mpc_copy(a);
if (!copy) { FUZZ_BAIL(); }
// Propagate known attributes when available.
int is_ph = FUZZ_GET_ATTR_INT(a, "is_placeholder");
int is_def = FUZZ_GET_ATTR_INT(a, "is_defined");
if (is_ph) { FUZZ_SET_ATTR_INT(copy, "is_placeholder", is_ph); }
if (is_def || is_ph) { FUZZ_SET_ATTR_INT(copy, "is_defined", is_def); }
// Return both original and copy.

// mpc_define: define placeholder parser p with implementation a.
if (!p || !a) { FUZZ_BAIL(); }
// Enforce that p was created by mpc_new and is not yet defined.
int was_placeholder = FUZZ_GET_ATTR_INT(p, "is_placeholder");
int was_defined = FUZZ_GET_ATTR_INT(p, "is_defined");
if (!was_placeholder || was_defined) { FUZZ_BAIL(); }
mpc_parser_t *ret = mpc_define(p, a);
if (!ret) { FUZZ_BAIL(); }
// Update attributes to reflect defined state.
FUZZ_SET_ATTR_INT(p, "is_defined", 1);
FUZZ_SET_ATTR_INT(p, "is_placeholder", 0);
// Return both parsers (ownership unchanged).

// mpc_undefine: remove definition from parser p.
if (!p) { FUZZ_BAIL(); }
mpc_parser_t *ret = mpc_undefine(p);
if (!ret) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(p, "is_defined", 0);
FUZZ_SET_ATTR_INT(p, "is_placeholder", 1);
// Return parser for further operations.

// mpc_delete: destroy a parser and its resources.
if (!p) { FUZZ_BAIL(); }
mpc_delete(p);
// Do not return p; it is invalid after deletion.

// mpc_cleanup: delete multiple parsers via variadic interface.
// Create a small set of parsers to pass; keep count consistent with args.
mpc_parser_t *ps[4];
int n = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // 1..4
for (int i = 0; i < n; ++i) {
  switch (i % 4) {
    case 0: ps[i] = mpc_any(); break;
    case 1: ps[i] = mpc_digit(); break;
    case 2: ps[i] = mpc_alpha(); break;
    default: ps[i] = mpc_pass(); break;
  }
  if (!ps[i]) { FUZZ_BAIL(); }
}
// Call variadic cleanup with exactly n pointers.
switch (n) {
  case 1: mpc_cleanup(1, ps[0]); break;
  case 2: mpc_cleanup(2, ps[0], ps[1]); break;
  case 3: mpc_cleanup(3, ps[0], ps[1], ps[2]); break;
  default: mpc_cleanup(4, ps[0], ps[1], ps[2], ps[3]); break;
}
// All created parsers are consumed; no outputs.

// mpc_any: parser that consumes any single character.
mpc_parser_t *p = mpc_any();
if (!p) { FUZZ_BAIL(); }
// Return newly created parser.

// mpc_char: parser that matches an exact character.
unsigned int u = *FUZZ_PARAM(unsigned int);
char c = (char)(u & 0xFF);
mpc_parser_t *p = mpc_char(c);
if (!p) { FUZZ_BAIL(); }
// Return parser.

// mpc_range: parser matching a character in inclusive range [s,e].
unsigned int u1 = *FUZZ_PARAM(unsigned int);
unsigned int u2 = *FUZZ_PARAM(unsigned int);
char s = (char)(u1 & 0xFF);
char e = (char)(u2 & 0xFF);
if (e < s) { char t = s; s = e; e = t; }
mpc_parser_t *p = mpc_range(s, e);
if (!p) { FUZZ_BAIL(); }
// Return parser.

// mpc_oneof: parser matching any one char from provided set string.
std::string set = FUZZ_PARAM_STR();
// Ensure non-empty NUL-terminated string for valid construction.
if (set.empty()) { FUZZ_BAIL(); }
mpc_parser_t *p = mpc_oneof(set.c_str());
if (!p) { FUZZ_BAIL(); }
// Return parser.

// mpc_noneof: parser matching any char not present in set string.
std::string set = FUZZ_PARAM_STR();
if (set.empty()) { FUZZ_BAIL(); }
mpc_parser_t *p = mpc_noneof(set.c_str());
if (!p) { FUZZ_BAIL(); }
// Return parser.

// mpc_string: create a parser that matches the exact string s.
std::string s = FUZZ_PARAM_STR();
mpc_parser_t *p = mpc_string(s.c_str());
if (!p) { FUZZ_BAIL(); }
// Mark that this parser produces a C-string value on success (common for literal matchers in MPC).
FUZZ_SET_ATTR_INT(p, "produces_cstr", 1);
FUZZ_SET_ATTR_INT(p, "produces_null", 0);
// Validation: parser pointer is non-null and tagged with value-type attributes.

// mpc_pass: parser that always succeeds without consuming input.
mpc_parser_t *p = mpc_pass();
if (!p) { FUZZ_BAIL(); }
// Typically yields a null/placeholder value.
FUZZ_SET_ATTR_INT(p, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(p, "produces_null", 1);
// Validation: p non-null; value-type attributes recorded.

// mpc_fail: parser that always fails with message m.
std::string msg = FUZZ_PARAM_STR();
if (msg.empty()) { FUZZ_BAIL(); }
mpc_parser_t *p = mpc_fail(msg.c_str());
if (!p) { FUZZ_BAIL(); }
// On success (never), value type is irrelevant; mark null to be conservative.
FUZZ_SET_ATTR_INT(p, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(p, "produces_null", 1);
// Validation: p created; message non-empty to satisfy requirement.

// mpc_failf: formatted failure parser. Use a format with no specifiers to avoid variadic args.
const char *fmt = "static failure"; // no % specifiers, so no extra args required
mpc_parser_t *p = mpc_failf(fmt);
if (!p) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(p, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(p, "produces_null", 1);
// Validation: p non-null; fmt is valid C string with zero variadic arguments.

// mpc_lift: produce a value by invoking a constructor without consuming input.
// Choose between known constructors: mpcf_ctor_null and mpcf_ctor_str.
unsigned int pick = *FUZZ_PARAM(unsigned int);
mpc_ctor_t ctor = (pick & 1u) ? mpcf_ctor_null : mpcf_ctor_str;
mpc_parser_t *p = mpc_lift(ctor);
if (!p) { FUZZ_BAIL(); }
// Tag produced value type according to constructor choice.
if (ctor == mpcf_ctor_str) {
  FUZZ_SET_ATTR_INT(p, "produces_cstr", 1);
  FUZZ_SET_ATTR_INT(p, "produces_null", 0);
} else {
  FUZZ_SET_ATTR_INT(p, "produces_cstr", 0);
  FUZZ_SET_ATTR_INT(p, "produces_null", 1);
}
// Validation: p created; attributes reflect constructor semantics.

// mpc_lift_val: yield the provided value x without consuming input.
// Provide a heap-allocated string so downstream appliers expecting strings are valid.
std::string sv = FUZZ_PARAM_STR();
char *heap_str = (char*)malloc(sv.size() + 1);
if (!heap_str) { FUZZ_BAIL(); }
memcpy(heap_str, sv.c_str(), sv.size() + 1);
mpc_val_t *x = (mpc_val_t*)heap_str;
mpc_parser_t *p = mpc_lift_val(x);
if (!p) { FUZZ_BAIL(); }
// The parser will own/propagate this value per MPC semantics.
FUZZ_SET_ATTR_INT(p, "produces_cstr", 1);
FUZZ_SET_ATTR_INT(p, "produces_null", 0);
// Validation: p non-null; value allocated on heap to satisfy potential freeing by MPC.

// mpc_state: parser that yields current input state.
mpc_parser_t *p = mpc_state();
if (!p) { FUZZ_BAIL(); }
// State is not a C-string; mark as non-string value.
FUZZ_SET_ATTR_INT(p, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(p, "produces_null", 0);
// Validation: p created and tagged conservatively.

// mpc_expect: wrap parser a to override its error message with e.
if (!a) { FUZZ_BAIL(); }
std::string emsg = FUZZ_PARAM_STR();
if (emsg.empty()) { FUZZ_BAIL(); }
mpc_parser_t *wrapped = mpc_expect(a, emsg.c_str());
if (!wrapped) { FUZZ_BAIL(); }
// Propagate known value-type attributes from a to the wrapper.
int produces_cstr = FUZZ_GET_ATTR_INT(a, "produces_cstr");
int produces_null = FUZZ_GET_ATTR_INT(a, "produces_null");
FUZZ_SET_ATTR_INT(wrapped, "produces_cstr", produces_cstr);
FUZZ_SET_ATTR_INT(wrapped, "produces_null", produces_null);
// Validation: both a and wrapped are returned; message is valid C string.

// mpc_expectf: formatted expect; use a format with no specifiers.
if (!a) { FUZZ_BAIL(); }
const char *fmt = "expected something"; // no % specifiers
mpc_parser_t *wrapped = mpc_expectf(a, fmt);
if (!wrapped) { FUZZ_BAIL(); }
// Propagate attributes from a to wrapped.
int produces_cstr = FUZZ_GET_ATTR_INT(a, "produces_cstr");
int produces_null = FUZZ_GET_ATTR_INT(a, "produces_null");
FUZZ_SET_ATTR_INT(wrapped, "produces_cstr", produces_cstr);
FUZZ_SET_ATTR_INT(wrapped, "produces_null", produces_null);
// Validation: valid wrap without variadic args; attributes preserved.

// mpc_apply: apply a post-processing function to value from parser a.
if (!a) { FUZZ_BAIL(); }
// Enforce that a produces a C-string compatible with selected appliers.
int produces_cstr = FUZZ_GET_ATTR_INT(a, "produces_cstr");
if (!produces_cstr) { FUZZ_BAIL(); }
// Choose a safe applier that expects strings.
unsigned int pick = *FUZZ_PARAM(unsigned int) % 6u;
mpc_apply_t f = nullptr;
switch (pick) {
  case 0: f = mpcf_strtriml; break;
  case 1: f = mpcf_strtrimr; break;
  case 2: f = mpcf_strtrim;  break;
  case 3: f = mpcf_escape;   break;
  case 4: f = mpcf_unescape; break;
  default: f = mpcf_str_ast; break; // library-defined, but string-compatible
}
mpc_parser_t *applied = mpc_apply(a, f);
if (!applied) { FUZZ_BAIL(); }
// Resulting value type may change; conservatively clear produces_cstr/null.
FUZZ_SET_ATTR_INT(applied, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(applied, "produces_null", 0);
// Validation: only string-producing parsers are accepted to satisfy applier preconditions.

// mpc_not: negative lookahead on parser a; does not consume input.
if (!a) { FUZZ_BAIL(); }
// Use null-destructor to safely handle any value produced by a during lookahead.
mpc_dtor_t da = mpcf_dtor_null;
mpc_parser_t *neg = mpc_not(a, da);
if (!neg) { FUZZ_BAIL(); }
// Negative lookahead typically produces no value; mark as null-producing.
FUZZ_SET_ATTR_INT(neg, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(neg, "produces_null", 1);
// Validation: a remains valid; resulting parser marked as producing null value.

// mpc_not_lift: negative lookahead that on success produces a value via lf.
if (!a) { FUZZ_BAIL(); }
mpc_dtor_t da = mpcf_dtor_null;
unsigned int pick = *FUZZ_PARAM(unsigned int);
mpc_ctor_t lf = (pick & 1u) ? mpcf_ctor_null : mpcf_ctor_str;
mpc_parser_t *neg = mpc_not_lift(a, da, lf);
if (!neg) { FUZZ_BAIL(); }
if (lf == mpcf_ctor_str) {
  FUZZ_SET_ATTR_INT(neg, "produces_cstr", 1);
  FUZZ_SET_ATTR_INT(neg, "produces_null", 0);
} else {
  FUZZ_SET_ATTR_INT(neg, "produces_cstr", 0);
  FUZZ_SET_ATTR_INT(neg, "produces_null", 1);
}
// Validation: constructed with valid destructor/constructor; attributes reflect constructor.

// mpc_maybe: optional combinator; succeeds even if a fails, often yielding null.
if (!a) { FUZZ_BAIL(); }
mpc_parser_t *opt = mpc_maybe(a);
if (!opt) { FUZZ_BAIL(); }
// The resulting parser may yield null when a fails; conservatively mark as possibly null.
// Keep produces_cstr conservative (unknown after optional).
FUZZ_SET_ATTR_INT(opt, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(opt, "produces_null", 1);
// Validation: a preserved and opt created; attributes conservative for downstream checks.

// mpc_maybe_lift: optional with default via constructor lf.
// Requirements: a must be a valid parser; lf must be a valid constructor.
if (!a) { FUZZ_BAIL(); }
unsigned int pick = *FUZZ_PARAM(unsigned int);
mpc_ctor_t lf = (pick & 1u) ? mpcf_ctor_null : mpcf_ctor_str;
mpc_parser_t *opt = mpc_maybe_lift(a, lf);
if (!opt) { FUZZ_BAIL(); }
// Tag resulting value characteristics based on constructor.
if (lf == mpcf_ctor_str) {
  FUZZ_SET_ATTR_INT(opt, "produces_cstr", 1);
  FUZZ_SET_ATTR_INT(opt, "produces_null", 0);
} else {
  FUZZ_SET_ATTR_INT(opt, "produces_cstr", 0);
  FUZZ_SET_ATTR_INT(opt, "produces_null", 1);
}
// Validation: a preserved and returned; opt created and attributes set.

// mpc_many: zero-or-more repetition folding with f.
// Requirements: a valid; f a valid fold function.
if (!a) { FUZZ_BAIL(); }
// Choose fold based on known value type when available.
int a_str = FUZZ_GET_ATTR_INT(a, "produces_cstr");
mpc_fold_t f = a_str ? mpcf_strfold : mpcf_null;
mpc_parser_t *many = mpc_many(f, a);
if (!many) { FUZZ_BAIL(); }
// Result value type after fold is unknown; clear attributes conservatively.
FUZZ_SET_ATTR_INT(many, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(many, "produces_null", 0);
// Validation: a is returned; many created; fold chosen safely for known string producers.

// mpc_many1: one-or-more repetition folding with f.
// Requirements: a valid; f a valid fold function.
if (!a) { FUZZ_BAIL(); }
int a_str = FUZZ_GET_ATTR_INT(a, "produces_cstr");
mpc_fold_t f = a_str ? mpcf_strfold : mpcf_null;
mpc_parser_t *many1 = mpc_many1(f, a);
if (!many1) { FUZZ_BAIL(); }
// Unknown resulting value characteristics; clear conservatively.
FUZZ_SET_ATTR_INT(many1, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(many1, "produces_null", 0);
// Validation: a preserved; many1 constructed.

// mpc_count: parse exactly n occurrences of a, fold with f, cleanup via da.
if (!a) { FUZZ_BAIL(); }
// Keep n small for performance; allow zero to exercise edge-case.
int n = (int)(*FUZZ_PARAM(unsigned int) % 4u); // 0..3
int a_str = FUZZ_GET_ATTR_INT(a, "produces_cstr");
mpc_fold_t f = a_str ? mpcf_strfold : mpcf_null;
mpc_dtor_t da = mpcf_dtor_null; // safe no-op for generic values
mpc_parser_t *counted = mpc_count(n, f, a, da);
if (!counted) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(counted, "produces_cstr", 0);
FUZZ_SET_ATTR_INT(counted, "produces_null", 0);
// Validation: a returned; counted created with consistent n and function pointers.

// mpc_or: ordered choice among n parsers. Build a small set locally.
mpc_parser_t *ps[4];
int n = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // 1..4
for (int i = 0; i < n; ++i) {
  switch (i % 4) {
    case 0: ps[i] = mpc_any(); break;
    case 1: ps[i] = mpc_alpha(); break;
    case 2: ps[i] = mpc_digit(); break;
    default: ps[i] = mpc_pass(); break;
  }
  if (!ps[i]) { FUZZ_BAIL(); }
}
mpc_parser_t *choice = nullptr;
switch (n) {
  case 1: choice = mpc_or(1, ps[0]); break;
  case 2: choice = mpc_or(2, ps[0], ps[1]); break;
  case 3: choice = mpc_or(3, ps[0], ps[1], ps[2]); break;
  default: choice = mpc_or(4, ps[0], ps[1], ps[2], ps[3]); break;
}
if (!choice) { FUZZ_BAIL(); }
// Value type unknown; leave attributes unset conservatively.

// mpc_and: sequence of n parsers folded with f.
// Use a value-agnostic fold that returns NULL to avoid type assumptions.
mpc_fold_t f = mpcf_null;
mpc_parser_t *ps[3];
int n = (int)(*FUZZ_PARAM(unsigned int) % 3u) + 1; // 1..3
for (int i = 0; i < n; ++i) {
  switch (i % 3) {
    case 0: ps[i] = mpc_string(FUZZ_PARAM_STR().c_str()); break;
    case 1: ps[i] = mpc_whitespace(); break;
    default: ps[i] = mpc_any(); break;
  }
  if (!ps[i]) { FUZZ_BAIL(); }
}
mpc_parser_t *seq = nullptr;
switch (n) {
  case 1: seq = mpc_and(1, f, ps[0]); break;
  case 2: seq = mpc_and(2, f, ps[0], ps[1]); break;
  default: seq = mpc_and(3, f, ps[0], ps[1], ps[2]); break;
}
if (!seq) { FUZZ_BAIL(); }
// Result value characteristics unknown; no attributes set.

// mpc_predictive: enable predictive behavior for parser a.
if (!a) { FUZZ_BAIL(); }
mpc_parser_t *pred = mpc_predictive(a);
if (!pred) { FUZZ_BAIL(); }
// Preserve value-type attributes from a as predictive shouldn't change value type.
int produces_cstr = FUZZ_GET_ATTR_INT(a, "produces_cstr");
int produces_null = FUZZ_GET_ATTR_INT(a, "produces_null");
FUZZ_SET_ATTR_INT(pred, "produces_cstr", produces_cstr);
FUZZ_SET_ATTR_INT(pred, "produces_null", produces_null);
// Validation: both a and pred returned; attributes propagated.

// mpc_eoi: end-of-input parser.
mpc_parser_t *p = mpc_eoi();
if (!p) { FUZZ_BAIL(); }
// Conservatively no value-type attributes set.

// mpc_soi: start-of-input parser.
mpc_parser_t *p = mpc_soi();
if (!p) { FUZZ_BAIL(); }

// mpc_boundary: word-boundary-like parser.
mpc_parser_t *p = mpc_boundary();
if (!p) { FUZZ_BAIL(); }

// mpc_boundary_newline: newline-sensitive boundary parser.
mpc_parser_t *p = mpc_boundary_newline();
if (!p) { FUZZ_BAIL(); }

